    'SLH-DSA-SHA2-192f': S.slh_dsa_sha2_192f,
    'SLH-DSA-SHA2-256s': S.slh_dsa_sha2_256s,
    'SLH-DSA-SHA2-256f': S.slh_dsa_sha2_256f,
