describe('SLH-DSA-keyGen-FIPS205 (NIST CAVP, 36 sub-samples / 120 total)', () => {
    test.each(_KG_SLH)(
        'tgId=$tg tcId=$tc ($ps): keygen(skSeed||skPrf||pkSeed) == (pk, sk)',
        (v) => {
            const seed = new Uint8Array(_hex.toBytes(v.skSeed).length * 3);
            const skSeed = _hex.toBytes(v.skSeed);
            const skPrf  = _hex.toBytes(v.skPrf);
            const pkSeed = _hex.toBytes(v.pkSeed);
            seed.set(skSeed, 0);
            seed.set(skPrf, skSeed.length);
            seed.set(pkSeed, skSeed.length + skPrf.length);
            const kp = _SLH[v.ps].keygen(seed);
            expect(kp).not.toBe(false);
            expect(_hex.fromBytes(kp.publicKey)).toBe(v.pk.toLowerCase());
            expect(_hex.fromBytes(kp.secretKey)).toBe(v.sk.toLowerCase());
        },
        120_000
    );
});

describe('SLH-DSA-sigGen-FIPS205 / external+pure deterministic (NIST CAVP, 2 byte-exact 128f vectors)', () => {
    test.each(_SG_SLH)(
        'tgId=$tg tcId=$tc ($ps): sign(msg, sk, {context, extraEntropy:false}) == signature',
        (v) => {
            const sk  = _hex.toBytes(v.sk);
            const msg = _hex.toBytes(v.msg);
            const ctx = v.ctx ? _hex.toBytes(v.ctx) : new Uint8Array(0);
            const sig = _SLH[v.ps].sign(msg, sk, { context: ctx, extraEntropy: false });
            expect(sig).not.toBe(false);
            expect(_hex.fromBytes(sig)).toBe(v.sig.toLowerCase());
        },
        300_000
    );
});

describe('SLH-DSA-sigVer-FIPS205 / external+pure (NIST CAVP, 18 sub-samples on f-variants)', () => {
    test.each(_SV_SLH)(
        'tgId=$tg tcId=$tc ($ps, expected=$pass, reason=$reason): verify(sig, msg, pk, {context})',
        (v) => {
            const pk  = _hex.toBytes(v.pk);
            const msg = _hex.toBytes(v.msg);
            const sig = _hex.toBytes(v.sig);
            const ctx = v.ctx ? _hex.toBytes(v.ctx) : new Uint8Array(0);
            const ok = _SLH[v.ps].verify(sig, msg, pk, { context: ctx });
            expect(ok).toBe(v.pass);
        },
        120_000
    );
});


// ============================================================================
// SLH-DSA HashSLH-DSA + internal interface - iteration E4 of the upgrade plan
// ----------------------------------------------------------------------------
// Sources:
//   SLH-DSA-sigGen-FIPS205 / external+preHash det=true (128f only): 2 vectors
//   SLH-DSA-sigGen-FIPS205 / internal det=true (128f only): 2 vectors
//   SLH-DSA-sigVer-FIPS205 / external+preHash 'f' variants: 12 vectors
//   SLH-DSA-sigVer-FIPS205 / internal 'f' variants: 12 vectors
//
// Note: SLH-DSA does NOT have an externalMu mode (no mu intermediate in
// FIPS 205 §6; hashing is integrated into the PRFmsg + Hmsg + FORS + HT pipeline).
//
// Aggressive SigGen sub-sampling: sign 's' variants = minutes/vector,
// sign 192f/256f = 30-90 s. Limited to 1 byte-exact vector per 128f variant
// to preserve the module budget. SigVer 'f' variants: 2 vectors/group
// [first valid, first modified].
// ============================================================================

