describe('SLH-DSA-sigGen / external+preHash (HashSLH-DSA, iteration E4)', () => {
    test.each(_SG_PH_SLH)(
        'tgId=$tg tcId=$tc ($ps, hashAlg=$hashAlg): signPh byte-exact',
        (v) => {
            const sk = _hex.toBytes(v.sk);
            const msg = _hex.toBytes(v.msg);
            const ctx = v.ctx ? _hex.toBytes(v.ctx) : new Uint8Array(0);
            const hashMod = _SLH_HASH_E4[v.hashAlg];
            const sig = _SLH_E4[v.ps].signPh(msg, sk, v.hashAlg, hashMod, { context: ctx, extraEntropy: false });
            expect(sig).not.toBe(false);
            expect(_hex.fromBytes(sig)).toBe(v.sig.toLowerCase());
        },
        300_000
    );
});

describe('SLH-DSA-sigGen / internal (FIPS 205 §6 raw, iteration E4)', () => {
    test.each(_SG_INT_SLH)(
        'tgId=$tg tcId=$tc ($ps): _internal.signInternal byte-exact',
        (v) => {
            const sk = _hex.toBytes(v.sk);
            const Mraw = _hex.toBytes(v.msg);
            const sig = _SLH_E4[v.ps]._internal.signInternal(Mraw, sk, { extraEntropy: false });
            expect(sig).not.toBe(false);
            expect(_hex.fromBytes(sig)).toBe(v.sig.toLowerCase());
        },
        300_000
    );
});

describe('SLH-DSA-sigVer / external+preHash (HashSLH-DSA, iteration E4)', () => {
    test.each(_SV_PH_SLH)(
        'tgId=$tg tcId=$tc ($ps, $hashAlg, expected=$pass, reason=$reason): verifyPh',
        (v) => {
            const pk = _hex.toBytes(v.pk);
            const msg = _hex.toBytes(v.msg);
            const sig = _hex.toBytes(v.sig);
            const ctx = v.ctx ? _hex.toBytes(v.ctx) : new Uint8Array(0);
            const hashMod = _SLH_HASH_E4[v.hashAlg];
            const ok = _SLH_E4[v.ps].verifyPh(sig, msg, pk, v.hashAlg, hashMod, { context: ctx });
            expect(ok).toBe(v.pass);
        },
        120_000
    );
});

describe('SLH-DSA-sigVer / internal (FIPS 205 §6 raw, iteration E4)', () => {
    test.each(_SV_INT_SLH)(
        'tgId=$tg tcId=$tc ($ps, expected=$pass, reason=$reason): verifyInternal',
        (v) => {
            const pk = _hex.toBytes(v.pk);
            const Mraw = _hex.toBytes(v.msg);
            const sig = _hex.toBytes(v.sig);
            const ok = _SLH_E4[v.ps]._internal.verifyInternal(sig, Mraw, pk);
            expect(ok).toBe(v.pass);
        },
        120_000
    );
});

// ── Iteration H3 - Full ACVP coverage gated behind CRYPTO_FULL ───────────────
//
// The `CRYPTO_FULL=1` flag unlocks all keyGen vectors (120/120) and
// sigVer external+pure. Full sigGen (624) is intentionally **not wired**:
// SLH-DSA sign costs seconds/op (up to minutes for 's' variants),
// estimated totals in hours. The E4 sub-sample validates the path. Without
// the flag, the default suite is unchanged.
const RUN_FULL_H3 = process.env.CRYPTO_FULL === '1';
if (RUN_FULL_H3) {
    const { readFileSync } = await import('node:fs');
    const _ROOT = new URL('../../../tests/_vectors/', import.meta.url);
    const _load = (name) => {
        const p = JSON.parse(readFileSync(new URL(`${name}/internalProjection.json`, _ROOT), 'utf8'));
        const e = JSON.parse(readFileSync(new URL(`${name}/expectedResults.json`, _ROOT), 'utf8'));
        const expByTc = new Map();
        for (const g of e.testGroups) for (const t of g.tests) expByTc.set(t.tcId, t);
        const out = [];
        for (const g of p.testGroups) {
            for (const t of g.tests) {
                out.push({
                    tg: g.tgId, tc: t.tcId, ps: g.parameterSet,
                    preHash: g.preHash, sigInterface: g.signatureInterface,
                    deterministic: g.deterministic,
                    ...t, ...expByTc.get(t.tcId),
                });
            }
        }
        return out;
    };

    describe('SLH-DSA-keyGen-FIPS205 - full ACVP (CRYPTO_FULL, 120/120)', () => {
        const ALL = _load('SLH-DSA-keyGen-FIPS205');
        test.each(ALL)('tgId=$tg tcId=$tc ($ps)', (v) => {
            const skSeed = _hex.toBytes(v.skSeed);
            const skPrf  = _hex.toBytes(v.skPrf);
            const pkSeed = _hex.toBytes(v.pkSeed);
            const seed = new Uint8Array(skSeed.length + skPrf.length + pkSeed.length);
            seed.set(skSeed, 0);
            seed.set(skPrf, skSeed.length);
            seed.set(pkSeed, skSeed.length + skPrf.length);
            const kp = _SLH[v.ps].keygen(seed);
            expect(_hex.fromBytes(kp.publicKey)).toBe(v.pk.toLowerCase());
            expect(_hex.fromBytes(kp.secretKey)).toBe(v.sk.toLowerCase());
        }, 120_000);
    });

    describe('SLH-DSA-sigVer-FIPS205 - full ACVP external+pure (CRYPTO_FULL)', () => {
        const ALL = _load('SLH-DSA-sigVer-FIPS205').filter(v => v.preHash === 'pure' && v.sigInterface === 'external');
        test.each(ALL)('tgId=$tg tcId=$tc ($ps, expected=$testPassed)', (v) => {
            const ctx = v.context ? _hex.toBytes(v.context) : new Uint8Array(0);
            const ok = _SLH[v.ps].verify(_hex.toBytes(v.signature), _hex.toBytes(v.message), _hex.toBytes(v.pk), { context: ctx });
            expect(ok).toBe(v.testPassed);
        }, 300_000);
    });
}
